SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['1b1f1db9-6e91-4cf5-8852-e11dfac760b8','c76d9283-f8c4-47eb-8a8a-7adb9515ff64','0533fc6d-257a-4c31-96d8-2e834138ee69']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['1b1f1db9-6e91-4cf5-8852-e11dfac760b8','c76d9283-f8c4-47eb-8a8a-7adb9515ff64','0533fc6d-257a-4c31-96d8-2e834138ee69']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['1b1f1db9-6e91-4cf5-8852-e11dfac760b8','c76d9283-f8c4-47eb-8a8a-7adb9515ff64','0533fc6d-257a-4c31-96d8-2e834138ee69']::uuid[]) OR variant_id=ANY(ARRAY['cab43ba9-aaa5-4c7b-ae3d-f6fc35dec8c0','92c2f04b-30b3-486d-aa04-6a8c21d4a151','d7c39018-9660-4045-9311-ffc1083ba7fc']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['cdb922a5-eaec-4696-ae6f-3ad4d263c66b']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['1b1f1db9-6e91-4cf5-8852-e11dfac760b8','c76d9283-f8c4-47eb-8a8a-7adb9515ff64','0533fc6d-257a-4c31-96d8-2e834138ee69']::uuid[]) OR variant_id=ANY(ARRAY['cab43ba9-aaa5-4c7b-ae3d-f6fc35dec8c0','92c2f04b-30b3-486d-aa04-6a8c21d4a151','d7c39018-9660-4045-9311-ffc1083ba7fc']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['cdb922a5-eaec-4696-ae6f-3ad4d263c66b']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['1b1f1db9-6e91-4cf5-8852-e11dfac760b8','c76d9283-f8c4-47eb-8a8a-7adb9515ff64','0533fc6d-257a-4c31-96d8-2e834138ee69']::uuid[]) OR variant_id=ANY(ARRAY['cab43ba9-aaa5-4c7b-ae3d-f6fc35dec8c0','92c2f04b-30b3-486d-aa04-6a8c21d4a151','d7c39018-9660-4045-9311-ffc1083ba7fc']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['1b1f1db9-6e91-4cf5-8852-e11dfac760b8','c76d9283-f8c4-47eb-8a8a-7adb9515ff64','0533fc6d-257a-4c31-96d8-2e834138ee69']::uuid[]) OR variant_id=ANY(ARRAY['cab43ba9-aaa5-4c7b-ae3d-f6fc35dec8c0','92c2f04b-30b3-486d-aa04-6a8c21d4a151','d7c39018-9660-4045-9311-ffc1083ba7fc']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['cdb922a5-eaec-4696-ae6f-3ad4d263c66b']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['cdb922a5-eaec-4696-ae6f-3ad4d263c66b']::uuid[])) ORDER BY scope,identity;